function [I, K] = quadinv(At)
    A = At(1:3, 1:3);
    al = At(1:3, 4);
    a44 = At(4, 4);
    I1 = trace(A);
    I2 = 0.5 * (I1^2 - trace(A^2));
    I3 = det(A);
    I4 = det(At);
    K1 = I1 * a44 - (al' * al);
    K2 = I2 * a44 - I1 * (al' * al) + al' * A * al;
    I = [I1, I2, I3, I4];
    K = [K1, K2];
end

function qtype = classify_quadric(At, tol)
    if nargin < 2, tol = 1e-10; end
    A = At(1:3, 1:3);
    [I, K] = quadinv(At);
    I1 = I(1); I2 = I(2); I3 = I(3); I4 = I(4);
    K1 = K(1); K2 = K(2);

    if abs(I3) > tol
        lam = eig(A);
        same_sign = all(lam > tol) || all(lam < -tol);
        if same_sign
            if I4 < -tol
                qtype = '椭球面';
            elseif I4 > tol
                qtype = '虚椭球面(空集)';
            else
                qtype = '一点';
            end
        else
            if I4 > tol
                qtype = '单叶双曲面';
            elseif I4 < -tol
                qtype = '双叶双曲面';
            else
                qtype = '二次锥面';
            end
        end
    elseif abs(I2) > tol
        if abs(I4) > tol
            if I2 > 0
                qtype = '椭圆抛物面';
            else
                qtype = '双曲抛物面';
            end
        else
            if I2 > 0
                if I1 * K2 < -tol
                    qtype = '椭圆柱面';
                elseif I1 * K2 > tol
                    qtype = '虚椭圆柱面(空集)';
                else
                    qtype = '一条直线';
                end
            else
                if abs(K2) > tol
                    qtype = '双曲柱面';
                else
                    qtype = '两个相交平面';
                end
            end
        end
    else
        if abs(K2) > tol
            qtype = '抛物柱面';
        else
            if K1 < -tol
                qtype = '两个平行平面';
            elseif K1 > tol
                qtype = '两个虚平行平面(空集)';
            else
                qtype = '两个重合平面';
            end
        end
    end
end
