function [tname, p, nvec, ang, b1] = classify_isometry(Q, b, tol)
    if nargin < 3, tol = 1e-10; end
    if det(Q) > 0
        if norm(Q - eye(3), 'fro') < tol
            tname = '平移';
            if norm(b) < tol, tname = '平移(恒等变换)'; end
            p = [0; 0; 0];
            nvec = [0; 0; 0];
            ang = 0;
            b1 = b;
        else
            nvec = null(Q - eye(3));
            nvec = nvec(:, 1) / norm(nvec(:, 1));
            ang = acos(max(-1, min(1, (trace(Q) - 1) / 2)));
            b1 = (b' * nvec) * nvec;
            b2 = b - b1;
            p = pinv(eye(3) - Q) * b2;
            if norm(b1) < tol
                tname = '旋转';
            else
                tname = '螺旋运动';
            end
        end
    else
        phi = acos(max(-1, min(1, (trace(Q) + 1) / 2)));
        ang = phi;
        if phi < tol
            nvec = null(Q + eye(3));
            nvec = nvec(:, 1) / norm(nvec(:, 1));
            V1 = null(Q - eye(3));
            b1 = V1 * (V1' * b);
            b2 = b - b1;
            p = pinv(eye(3) - Q) * b2;
            if norm(b1) < tol
                tname = '镜面反射';
